public interface IPricingStrategy
{
    decimal CalculateFee(Ticket ticket);
}

// Simple hourly rate per vehicle type
public class HourlyPricingStrategy : IPricingStrategy
{
    private readonly Dictionary<VehicleType, decimal> _hourlyRates;

    public HourlyPricingStrategy(Dictionary<VehicleType, decimal> hourlyRates)
    {
        _hourlyRates = hourlyRates;
    }

    public decimal CalculateFee(Ticket ticket)
    {
        var hours = (ticket.ExitTime!.Value - ticket.EntryTime).TotalHours;
        var rate = _hourlyRates[ticket.VehicleType];
        return (decimal)hours * rate;
    }
}

// Weekend surcharge wrapper
public class WeekendSurchargeStrategy : IPricingStrategy
{
    private readonly IPricingStrategy _inner;
    private readonly decimal _surchargePercent;

    public WeekendSurchargeStrategy(IPricingStrategy inner, decimal surchargePercent = 0.2m)
    {
        _inner = inner;
        _surchargePercent = surchargePercent;
    }

    public decimal CalculateFee(Ticket ticket)
    {
        var baseFee = _inner.CalculateFee(ticket);
        var day = ticket.ExitTime!.Value.DayOfWeek;
        if (day is DayOfWeek.Saturday or DayOfWeek.Sunday)
            return baseFee * (1 + _surchargePercent);
        return baseFee;
    }
}

public class ConcurrentParkingLot
{
    private readonly ParkingLot _inner;
    private readonly ReaderWriterLockSlim _lock = new();

    public ConcurrentParkingLot(ParkingLot inner) => _inner = inner;

    public Ticket ParkVehicle(VehicleType type)
    {
        _lock.EnterWriteLock();
        try
        {
            return _inner.ParkVehicle(type);
        }
        finally
        {
            _lock.ExitWriteLock();
        }
    }

    public decimal Exit(string ticketId)
    {
        _lock.EnterWriteLock();
        try
        {
            return _inner.Exit(ticketId);
        }
        finally
        {
            _lock.ExitWriteLock();
        }
    }
}
